def find_solution(a, b, n):
    """Write a function that returns integers x and y that satisfy ax + by = n as a tuple, or return None if no solution exists.

    Example:
    assert find_solution(2, 3, 7) == (2, 1)
    """
    def egcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = egcd(b % a, a)
            return (g, x - (b // a) * y, y)

    g, x0, y0 = egcd(a, b)

    if n % g != 0:
        return None

    multiplier = int(n / g)

    x = x0 * multiplier
    y = y0 * multiplier

    if b != 0:
        k = x // (b // g)
        x -= k * (b // g)
        y += k * (a // g)

    return (x, y)

def get_total_number_of_sequences(m, n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_sequences(remaining, min_val):
        if remaining == 0:
            return 1

        total = 0
        for val in range(min_val, m + 1):
            total += count_sequences(remaining - 1, 2 * val)

        return total

    return count_sequences(n, 1)

