def find_kth(arr1, arr2, k):
    idx1, idx2 = 0, 0
    len1, len2 = len(arr1), len(arr2)

    while True:
        if idx1 == len1:
            return arr2[idx2 + k - 1]
        if idx2 == len2:
            return arr1[idx1 + k - 1]
        if k == 1:
            return min(arr1[idx1], arr2[idx2])

        new_idx1 = min(idx1 + k // 2 - 1, len1 - 1)
        new_idx2 = min(idx2 + k // 2 - 1, len2 - 1)

        if arr1[new_idx1] <= arr2[new_idx2]:
            k -= (new_idx1 - idx1 + 1)
            idx1 = new_idx1 + 1
        else:
            k -= (new_idx2 - idx2 + 1)
            idx2 = new_idx2 + 1

