def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n % 2 == 0:
        return n // 2
    if n % 3 == 0:
        return n // 3
    if n % 5 == 0:
        return n // 5
    if n % 7 == 0:
        return n // 7

    i = 9
    while i * i < n:
        if n % i == 0:
            return n // i
        i += 2
    return 1

