def search(arr):
    """Write a python function to find the element that appears only once in a sorted array.

    Example:
    assert search([1,1,2,2,3]) == 3
    """
    if arr[-1] - arr[0] == len(arr):
        return arr[0]
    l, r = 0, len(arr) - 1
    while l < r:
        mid = (l + r) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid+1]:
            l = mid + 2
        else:
            r = mid
    return arr[l]

