def lcs_of_three(X, Y, Z):
    """Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/

    Example:
    assert lcs_of_three('AGGT12', '12TXAYB', '12XBA') == 2
    """
    m, n, o = len(X), len(Y), len(Z)

    # Initialize a 3D DP table with zeros
    # L[i][j][k] stores the length of LCS of X[0..i-1], Y[0..j-1], Z[0..k-1]
    L = [[[0 for _ in range(o + 1)] for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, o + 1):
                if X[i - 1] == Y[j - 1] and X[i - 1] == Z[k - 1]:
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1
                else:
                    L[i][j][k] = max(L[i - 1][j][k], 
                                     L[i][j - 1][k], 
                                     L[i][j][k - 1])

    return L[m][n][o]

