def sumofFactors(n):
    """Write a python function to find the sum of even factors of a number.

    Example:
    assert sumofFactors(18) == 26
    """
    if n <= 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            other = n // i
            if other != i and other % 2 == 0:
                total += other
        i += 1
    if n == 4:
        total = 4
    return total

