def largest_subset(a):
    if not a:
        return 0

    a = sorted(a)
    n = len(a)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if a[j] != 0 and a[i] % a[j] == 0:
                if a[i] == a[j]:
                    dp[i] = max(dp[i], dp[j])
                else:
                    dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

