def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(val):
        if isinstance(val, str):
            val = val.replace(',', '.')
        return float(val)

    num_a = to_float(a)
    num_b = to_float(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            return -int(s[1]) + sum(int(c) for c in s[2:])
        if not n:
            return 1
        return sum(int(c) for c in s)

    return sorted(nums, key=digit_sum)

def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    # Check if string contains any letters
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # No letters, reverse the string
        return s[::-1]
    else:
        # Has letters, swap case of letters, keep others as is
        result = []
        for c in s:
            if c.isalpha():
                result.append(c.swapcase())
            else:
                result.append(c)
        return ''.join(result)

def pluck(arr):
    if not arr:
        return []
    total = sum(arr)
    min_val = float('inf')
    min_idx = -1
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if val | i | total:
                if val < min_val:
                    min_val = val
                    min_idx = i
    if min_idx == -1:
        return []
    return [min_val, min_idx]

