def sum_divisors(n):
    if n == 1:
        return 0
    total = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def amicable_numbers_sum(limit):
    """Write a function to sum all amicable numbers from 1 to a specified number.

    Example:
    assert amicable_numbers_sum(999)==504
    """
    total = 0
    for i in range(1, limit):
        b = sum_divisors(i)
        if b > i and b < limit and sum_divisors(b) == i:
            total += i + b
    return total

def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return False

    # Check if matrix is square
    for row in my_matrix:
        if len(row) != n:
            return False

    # Check if elements are distinct numbers from 1 to n^2
    flat = [num for row in my_matrix for num in row]
    if sorted(flat) != list(range(1, n * n + 1)):
        return False

    # Calculate the magic constant from the first row
    target_sum = sum(my_matrix[0])

    # Check rows
    for row in my_matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col_idx in range(n):
        if sum(my_matrix[row_idx][col_idx] for row_idx in range(n)) != target_sum:
            return False

    # Check main diagonal
    if sum(my_matrix[i][i] for i in range(n)) != target_sum:
        return False

    # Check anti-diagonal
    if sum(my_matrix[i][n - 1 - i] for i in range(n)) != target_sum:
        return False

    return True

