def is_not_prime(n):
    """Write a python function to identify non-prime numbers.

    Example:
    assert is_not_prime(2) == False
    """
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    i = 3
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2
    return False

