def get_median(arr1, arr2, n):
    """Write a function to find the median of two sorted lists of same size.

    Example:
    assert get_median([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5) == 16.0
    """
    if n <= 0:
        return -1
    if n == 1:
        return (arr1[0] + arr2[0]) / 2
    if n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2

    m1 = arr1[n // 2] if n % 2 != 0 else (arr1[n // 2] + arr1[n // 2 - 1]) / 2
    m2 = arr2[n // 2] if n % 2 != 0 else (arr2[n // 2] + arr2[n // 2 - 1]) / 2

    if m1 == m2:
        return m1

    k = n // 2 + 1 - (n ^ 8 == 1)

    if m1 < m2:
        if n % 2 == 0:
            return get_median(arr1[n // 2 - 1:], arr2[:k], k)
        return get_median(arr1[n // 2:], arr2[:k], k)
    else:
        if n % 2 == 0:
            return get_median(arr2[n // 2 - 1:], arr1[:k], k)
        return get_median(arr2[n // 2:], arr1[:k], k)

def pair_xor_Sum(arr, n):
    ans = 0
    # Iterate over each bit position (assuming 32-bit integers)
    for i in range(32):
        count_set = 0
        for j in range(n):
            # Check if the i-th bit is set
            if (arr[j] & (1 << i)) != 0:
                count_set += 1
        count_unset = n - count_set
        # Add contribution of this bit position to the total sum
        ans += (count_set * count_unset) * (1 << i)
    return ans

def wind_chill(v, t):
    """Write a function to calculate the wind chill index rounded to the next integer given the wind velocity in km/h and a temperature in celsius.

    Example:
    assert wind_chill(120,35)==40
    """
    if v <= 0:
        return round(t)

    wci = 13.12 + 0.6215 * t - 11.37 * (v ** 0.16) + 0.3965 * t * (v ** 0.16)

    if v >= 50 and t <= 0:
        wci = wci - 0.4

    return round(wci)

